export function b58encodeInt(v) {
  // Mirrors the reference base58 implementation exactly, including its use
  // of Python-style floor division (divmod): for negative inputs the value
  // converges to -1 and the loop never terminates, just like the original.
  if (v === 0n) {
    return '1';
  }
  let result = '';
  while (v !== 0n) {
    let rem = v % 58n;
