6	 * Quote selection and escaping follow CPython's bytes_repr:
7	 * - default quote is a single quote; double quotes are used only when s
8	 *   contains a single quote but no double quote
9	 * - backslash and the active quote char are escaped with a backslash
10	 * - \t, \n, \r get their two-letter escapes
11	 * - any other byte outside printable ASCII 0x20-0x7E becomes \xNN
12	 *   (lowercase hex)
13	 */
14	export function bytesRepr(s) {
15	  const hasSingle = s.includes("'");
16	  const hasDouble = s.includes('"');
17	  const quote = hasSingle && !hasDouble ? '"' : "'";
18	
19	  let out = 'b' + quote;
20	  for (const ch of s) {
21	    const code = ch.charCodeAt(0);
22	    if (ch === '\\' || ch === quote) {
23	      out += '\\' + ch;
24	    } else if (ch === '\t') {
